using System.Text.Json;using Microsoft.Extensions.Options;using NexaConnect.Contracts.IntegrationEvents;using NexaConnect.Infrastructure.Messaging;using NexaConnect.Services.Reporting.Application;using RabbitMQ.Client;using RabbitMQ.Client.Events;
namespace NexaConnect.Services.Reporting.Infrastructure.Messaging;
public sealed class ActivityConsumerOptions{public bool Enabled{get;set;}public string ConnectionString{get;set;}="";public string Exchange{get;set;}="nexaconnect.events";public string Queue{get;set;}="nexaconnect.reporting.activity.v1";public ushort PrefetchCount{get;set;}=20;}
public sealed class ActivityProjectionConsumer(IConnection connection,IOptions<ActivityConsumerOptions> options,IDurableInboxStore inbox,IServiceScopeFactory scopes,ILogger<ActivityProjectionConsumer> logger):BackgroundService
{
 private const string Consumer="reporting.activity.v1";
 protected override async Task ExecuteAsync(CancellationToken stoppingToken){await using IChannel channel=await connection.CreateChannelAsync(cancellationToken:stoppingToken);await channel.ExchangeDeclareAsync(options.Value.Exchange,ExchangeType.Topic,durable:true,cancellationToken:stoppingToken);var arguments=new Dictionary<string,object?>{{"x-dead-letter-exchange",options.Value.Exchange},{"x-dead-letter-routing-key","reporting.activity.dead"}};await channel.QueueDeclareAsync(options.Value.Queue,durable:true,exclusive:false,autoDelete:false,arguments:arguments,cancellationToken:stoppingToken);await channel.QueueDeclareAsync(options.Value.Queue+".dead",durable:true,exclusive:false,autoDelete:false,cancellationToken:stoppingToken);await channel.QueueBindAsync(options.Value.Queue,options.Value.Exchange,"*.audit.v1",cancellationToken:stoppingToken);await channel.QueueBindAsync(options.Value.Queue+".dead",options.Value.Exchange,"reporting.activity.dead",cancellationToken:stoppingToken);await channel.BasicQosAsync(0,options.Value.PrefetchCount,false,stoppingToken);var consumer=new AsyncEventingBasicConsumer(channel);consumer.ReceivedAsync+=async(_,args)=>{try{PlatformAuditEventV1 audit=JsonSerializer.Deserialize<PlatformAuditEventV1>(args.Body.Span)??throw new JsonException("Audit event is empty.");string source=args.RoutingKey switch{"platform-directory.audit.v1"=>"platform-directory","restaurant.audit.v1"=>"restaurant","media.audit.v1"=>"media",_=>throw new InvalidOperationException("Audit routing key is not allowed.")};InboxClaimResult claim=await inbox.ClaimAsync(audit.EventId,Consumer,TimeSpan.FromMinutes(2),stoppingToken);if(claim==InboxClaimResult.Busy){await channel.BasicNackAsync(args.DeliveryTag,false,true,stoppingToken);return;}if(claim==InboxClaimResult.Completed){await channel.BasicAckAsync(args.DeliveryTag,false,stoppingToken);return;}try{using IServiceScope scope=scopes.CreateScope();await scope.ServiceProvider.GetRequiredService<ActivityService>().ProjectAsync(new(audit,"nexa_connect",source),stoppingToken);await inbox.MarkCompletedAsync(audit.EventId,Consumer,stoppingToken);logger.LogInformation("Activity event projected for event {EventId}, source {SourceService}",audit.EventId,source);await channel.BasicAckAsync(args.DeliveryTag,false,stoppingToken);}catch(Exception e){await inbox.ReleaseAsync(audit.EventId,Consumer,e.GetType().Name,stoppingToken);throw;}}catch(Exception e)when(e is JsonException or ArgumentException or InvalidOperationException){logger.LogError(e,"Permanent activity event rejection for routing key {RoutingKey}",args.RoutingKey);await channel.BasicNackAsync(args.DeliveryTag,false,false,stoppingToken);}catch(Exception e)when(e is not OperationCanceledException){logger.LogError(e,"Transient activity event projection failure for routing key {RoutingKey}",args.RoutingKey);await channel.BasicNackAsync(args.DeliveryTag,false,true,stoppingToken);}};await channel.BasicConsumeAsync(options.Value.Queue,false,consumer,stoppingToken);await Task.Delay(Timeout.Infinite,stoppingToken);}
}
public static class ActivityConsumerRegistration
{
 public static IServiceCollection AddActivityConsumer(this IServiceCollection services,IConfiguration configuration){services.Configure<ActivityConsumerOptions>(configuration.GetSection("ActivityConsumer"));if(!configuration.GetValue<bool>("ActivityConsumer:Enabled"))return services;string value=configuration["ActivityConsumer:ConnectionString"]??throw new InvalidOperationException("ActivityConsumer:ConnectionString is required when enabled.");services.AddSingleton<IConnection>(_=>new ConnectionFactory{Uri=new Uri(value)}.CreateConnectionAsync().GetAwaiter().GetResult());services.AddSingleton<IDurableInboxStore,PostgresInboxStore>();services.AddHostedService<ActivityProjectionConsumer>();return services;}
}
